// A tiny signal-based reactive core.
//  - signal(initial)  -> [get, set]
//  - computed(fn)     -> get() with lazy, auto-tracked dependencies
//  - effect(fn)       -> runs fn now and on dep changes; returns dispose()

let stack = []; // subscriber stack for dependency tracking
const pendingEffects = new Set();

function subscribe(node, dep) {
  dep.subs.add(node);
  node.deps.add(dep);
}

function unsubscribe(node) {
  for (const dep of node.deps) dep.subs.delete(node);
  node.deps.clear();
}

// Mark all downstream computeds dirty and queue every reachable effect.
function propagate(dep) {
  for (const sub of dep.subs) {
    if (sub.isComputed) {
      if (!sub.dirty) {
        sub.dirty = true;
        propagate(sub); // dirty flags ripple through the graph eagerly
      }
    } else {
      pendingEffects.add(sub); // Set => each effect queued at most once
    }
  }
}

function flushEffects() {
  // Drain loop: effects may set signals, queuing more effects.
  while (pendingEffects.size > 0) {
    const batch = [...pendingEffects];
    pendingEffects.clear();
    for (const effect of batch) effect.run();
  }
}

function trackAndRun(node, fn) {
  unsubscribe(node); // dynamic deps: re-collect from scratch every run
  stack.push(node);
  try {
    return fn();
  } finally {
    stack.pop();
  }
}

export function signal(initial) {
  const node = { isComputed: false, subs: new Set(), value: initial };
  const get = () => {
    const current = stack.at(-1);
    if (current) subscribe(current, node);
    return node.value;
  };
  const set = (value) => {
    if (Object.is(node.value, value)) return;
    node.value = value;
    propagate(node);
    flushEffects();
  };
  return [get, set];
}

export function computed(fn) {
  const node = {
    isComputed: true,
    subs: new Set(),
    deps: new Set(),
    fn,
    value: undefined,
    dirty: false,
    initialized: false,
  };
  const get = () => {
    const current = stack.at(-1);
    if (current) subscribe(current, node);
    if (!node.initialized || node.dirty) {
      node.dirty = false;
      node.value = trackAndRun(node, fn);
      node.initialized = true;
    }
    return node.value;
  };
  get.dispose = () => unsubscribe(node);
  return get;
}

export function effect(fn) {
  let disposed = false;
  const node = {
    isComputed: false,
    deps: new Set(),
    run() {
      if (disposed) return;
      trackAndRun(node, fn);
    },
  };
  node.run(); // run immediately, collecting initial dependencies
  return () => {
    disposed = true;
    pendingEffects.delete(node);
    unsubscribe(node);
  };
}

