import test from 'node:test';
import assert from 'node:assert/strict';
import { signal, computed, effect } from './signals.mjs';

test('computed is lazy and caches', () => {
  const [count, setCount] = signal(0);
  let calls = 0;
  const double = computed(() => {
    calls++;
    return count() * 2;
  });

  assert.equal(calls, 0, 'not evaluated at creation');
  assert.equal(double(), 0);
  assert.equal(double(), 0);
  assert.equal(calls, 1, 'cached after first read');

  setCount(2); // marks dirty only; still no evaluation
  assert.equal(calls, 1, 'lazy: no recompute until read');
  assert.equal(double(), 4);
  assert.equal(calls, 2);

  setCount(3);
  setCount(4); // two writes before read
  assert.equal(double(), 8);
  assert.equal(calls, 3, 'one recompute per read regardless of write count');
});

test('dynamic dependency swap', () => {
  const [useA, setUseA] = signal(true);
  const [a, setA] = signal('a1');
  const [b, setB] = signal('b1');
  let calls = 0;
  const branch = computed(() => {
    calls++;
    return useA() ? a() : b();
  });

  assert.equal(branch(), 'a1');
  setB('b2');
  assert.equal(branch(), 'a1', 'b is not a dependency in this branch');
  assert.equal(calls, 1, 'no recompute when abandoned branch changes');

  setUseA(false);
  assert.equal(branch(), 'b2');
  setA('a2');
  assert.equal(branch(), 'b2', 'now a is the abandoned branch');
  assert.equal(branch(), 'b2');
  const before = calls;
  setB('b3');
  assert.equal(branch(), 'b3', 'reacts to newly adopted branch');
  assert.equal(calls, before + 1);
});

test('diamond dependency fires effect exactly once', () => {
  const [source, setSource] = signal(1);
  const left = computed(() => source() * 10);
  const right = computed(() => source() + 100);
  let runs = 0;
  let seen;
  effect(() => {
    runs++;
    seen = left() + right();
  });

  assert.equal(runs, 1, 'initial run');
  assert.equal(seen, 111);

  setSource(2); // one write feeding both computeds
  assert.equal(runs, 2, 'exactly one extra run, no glitch');
  assert.equal(seen, 122, 'effect observed a consistent state');

  setSource(3);
  setSource(4); // second write before flush of first? synchronous flush: separate batches
  assert.ok(runs >= 3 && runs <= 3, `runs=${runs}`);
  assert.equal(seen, 142);
});

test('dispose stops an effect', () => {
  const [x, setX] = signal(0);
  let runs = 0;
  const dispose = effect(() => {
    x();
    runs++;
  });

  assert.equal(runs, 1);
  setX(1);
  assert.equal(runs, 2);

  dispose();
  setX(2);
  setX(3);
  assert.equal(runs, 2, 'no runs after dispose');
});

test('effect tracks dynamically too', () => {
  const [on, setOn] = signal(true);
  const [v, setV] = signal(0);
  let runs = 0;
  const dispose = effect(() => {
    if (on()) v();
    runs++;
  });
  assert.equal(runs, 1);

  setOn(false);
  assert.equal(runs, 2);
  setV(99);
  assert.equal(runs, 2, 'v no longer tracked');
  dispose();
});

test('chained computed propagation', () => {
  const [base, setBase] = signal('x');
  const mid = computed(() => base().toUpperCase());
  const out = computed(() => `${mid()}!`);
  assert.equal(out(), 'X!');
  setBase('y');
  assert.equal(out(), 'Y!');
});

